{"url": "https://api.openalex.org/works?search=open+ended+learning+emergent+complexity+adaptive+systems&per-page=4&select=id%2Cdoi%2Ctitle%2Cpublication_year%2Ctype%2Ccited_by_count%2Copen_access%2Cprimary_location%2Cabstract_inverted_index", "scope": "OpenAlex scholarly metadata and reconstructed abstracts where supplied; not full papers", "excerpt": "[{"id": "https://openalex.org/W1971510005", "doi": "https://doi.org/10.1057/palgrave.jit.2000081", "title": "Complexity and Information Systems: The Emergent Domain", "publication_year": 2006, "type": "article", "cited_by_count": 106, "open_access": {"is_oa": true, "oa_status": "hybrid", "oa_url": "https://doi.org/10.1057/palgrave.jit.2000081", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1057/palgrave.jit.2000081", "doi": "https://doi.org/10.1057/palgrave.jit.2000081", "is_oa": true, "landing_page_url": "https://doi.org/10.1057/palgrave.jit.2000081", "pdf_url": null, "source": {"id": "https://openalex.org/S135086714", "display_name": "Journal of Information Technology", "issn_l": "0268-3962", "issn": ["0268-3962", "1466-4437"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["abdc-a-star", "anvur-class-a", "anvur-scientific", "cwts-core", "dongbi-c", "fnege-1", "jufo-3", "norway-2", "poland-140", "russia-white-list-1"], "host_organization": "https://openalex.org/P4310320017", "host_organization_name": "SAGE Publishing", "host_organization_lineage": ["https://openalex.org/P4310320017"], "host_organization_lineage_names": ["SAGE Publishing"], "type": "journal"}, "license": "cc-by-nc", "license_id": "https://openalex.org/licenses/cc-by-nc", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Journal of Information Technology", "raw_type": "journal-article"}, "abstract": "This paper is concerned with the emergence of the information systems (IS) domain as a central feature of the management research landscape in the networked world. It shows that emergence of the network economy and network society necessitates a paradigm shift in the IS discipline, and that complexity science offers the apposite concepts and tools for effecting such a shift. To avoid confusion of fundamental complexity science concepts with the more colloquial uses of complexity terminology, the paper provides an introduction to concepts from complexity science for those in the IS field who are unacquainted with complexity theory. It then proceeds to explore the utility of these concepts for developing IS theory and practice for the emergent networked world."}, {"id": "https://openalex.org/W1587668975", "doi": "https://doi.org/10.19173/irrodl.v12i3.883", "title": "Emergent learning and learning ecologies in Web 2.0", "publication_year": 2011, "type": "article", "cited_by_count": 201, "open_access": {"is

